const keyInput = document.getElementById("key-input");

keyInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") {
    console.log("Enter - wartosc:", e.target.value);
  }
  if (e.key === "Escape") {
    e.target.value = "";
  }
});

keyInput.addEventListener("keydown", (e) => {
  if (e.ctrlKey && e.key === "z") {
    e.preventDefault(); // blokuj domyslny Ctrl+Z (np. cofniecie w polu tekstowym)
    console.log("Zablokowano Ctrl+Z");
  }
});

keyInput.addEventListener("input", (e) => {
  console.log("Aktualna wartosc:", e.target.value); // przy KAZDEJ zmianie
});

document.getElementById("role")?.addEventListener("change", (e) => {
  console.log("Wybrana rola:", e.target.value); // dopiero PO utracie fokusu
});

keyInput.addEventListener("change", (e) => {
  console.log(e.target.value.length); // BLEDNIE - aktualizuje sie DOPIERO po utracie fokusu
});

keyInput.addEventListener("input", (e) => {
  console.log(e.target.value.length); // POPRAWNIE - aktualizuje sie NA BIEZACO
});

